// {{{ Source
// Forgejo's API answers all of this unauthenticated, because the repository is
// public -- so this workflow needs no credential at all. Do not "improve" it
// by adding a token: a token in n8n's store is one more thing to rotate for
// data that is already world-readable.
const FORGE = 'http://127.0.0.1:8409/api/v1';
const REPO = 'hugo-berendi/yomi';
const WEB = 'https://git.hugo-berendi.de';

const get = async (path, qs = {}) =>
  this.helpers.httpRequest({ method: 'GET', url: `${FORGE}/${path}`, qs, json: true, timeout: 20000 });

// This Forgejo (15.0.8) returns null for started_at/completed_at on both
// /actions/runs and /actions/tasks, so runs cannot be filtered by date at all.
// Ids are monotonic, so the report instead carries a cursor of the highest run
// it has already reported and covers everything above it. That also makes a
// missed week roll into the next report rather than vanishing.
// Forgejo caps a commits page well below what this repository produces: asking
// for 100 still returns 50, and 50 commits here can be two days rather than
// seven. So the commit section reports a floor ("50+") whenever the page came
// back full with its oldest entry still inside the window, instead of printing
// a page size as if it were a week's total.
const COMMIT_PAGE = 50;

const state = $getWorkflowStaticData('global');
const previousCursor = Number(state.lastReportedRunId ?? 0);

const [tasks, pulls, commits] = await Promise.all([
  get(`repos/${REPO}/actions/tasks`, { limit: 100 }),
  get(`repos/${REPO}/pulls`, { state: 'open', limit: 30 }),
  get(`repos/${REPO}/commits`, { limit: COMMIT_PAGE, stat: false, verification: false, files: false }),
]);

const allRuns = (tasks.workflow_runs ?? []).map((run) => ({
  id: run.id,
  number: run.run_number,
  workflow: run.workflow_id ?? run.name ?? 'unknown.yml',
  title: run.display_title ?? run.name ?? '',
  branch: run.head_branch ?? '',
  sha: (run.head_sha ?? '').slice(0, 8),
  event: run.event ?? '',
  status: run.status ?? 'unknown',
  url: run.url ?? `${WEB}/${REPO}/actions`,
}));

// First ever run: report the most recent handful rather than 220 rows.
const fresh = previousCursor === 0 ? allRuns.slice(0, 12) : allRuns.filter((r) => r.id > previousCursor);
const highest = allRuns.reduce((max, r) => Math.max(max, r.id), previousCursor);
// }}}

// {{{ Evaluation
const FAILED = new Set(['failure', 'cancelled', 'error']);
const RUNNING = new Set(['running', 'waiting', 'blocked', 'queued']);

const failures = fresh.filter((r) => FAILED.has(r.status));
const running = fresh.filter((r) => RUNNING.has(r.status));
const succeeded = fresh.filter((r) => !FAILED.has(r.status) && !RUNNING.has(r.status));

// A workflow that failed its most recent run is still broken now; one that
// failed and then passed has already been fixed and is only history. The
// distinction is the entire point of the report, so compute it per workflow
// over the full task list rather than over the reporting window.
const latestByWorkflow = new Map();
for (const run of allRuns) {
  if (!latestByWorkflow.has(run.workflow)) latestByWorkflow.set(run.workflow, run);
}
const brokenNow = [...latestByWorkflow.values()].filter((r) => FAILED.has(r.status));

const since = new Date(Date.now() - 7 * 86400e3);
const landed = (commits ?? [])
  .map((c) => ({
    sha: (c.sha ?? '').slice(0, 8),
    message: String(c.commit?.message ?? '').split('\n')[0],
    author: c.commit?.author?.name ?? c.author?.login ?? 'unknown',
    date: new Date(c.commit?.author?.date ?? c.created ?? Date.now()),
  }))
  .filter((c) => c.date >= since);

const commitsTruncated = (commits ?? []).length >= COMMIT_PAGE && landed.length === (commits ?? []).length;
const commitCount = commitsTruncated ? `${landed.length}+` : String(landed.length);

const openPulls = (pulls ?? []).map((p) => ({
  number: p.number,
  title: p.title,
  author: p.user?.login ?? 'unknown',
  age: Math.floor((Date.now() - new Date(p.created_at).getTime()) / 86400e3),
}));

const verdict = brokenNow.length ? 'nonconforming' : failures.length ? 'reviewed' : 'approved';

state.lastReportedRunId = highest;
// }}}

// {{{ Rosé Pine Moon, drafting dress
// Same palette as every other digest here (rose-pine-moon.yaml, the scheme
// the desktops use). Duplicated because n8n Code nodes cannot import.
//
// This one is a drawing of the repository's state, so it keeps its drafting
// structure -- rules, revision log, title block -- but in the shared colours:
// foam is the linework, pine the faint grid, love the red-pencil correction.
const rp = {
  base: '#232136',
  surface: '#2a273f',
  overlay: '#393552',
  muted: '#6e6a86',
  subtle: '#908caa',
  text: '#e0def4',
  love: '#eb6f92',
  gold: '#f6c177',
  rose: '#ea9a97',
  pine: '#3e8fb0',
  foam: '#9ccfd8',
  iris: '#c4a7e7',
  highlight: '#56526e',
};

const draft = "'Trebuchet MS','Lucida Grande',Tahoma,sans-serif";
const annot = "'Courier New',Courier,monospace";

const stamp = {
  approved: {label: 'APPROVED', colour: rp.foam, note: 'all workflows passing'},
  reviewed: {label: 'FOR REVIEW', colour: rp.gold, note: 'failures since fixed'},
  nonconforming: {label: 'NONCONFORMING', colour: rp.love, note: 'a workflow is broken now'},
}[verdict];

const short = (s, n) => (String(s).length > n ? `${String(s).slice(0, n - 1)}…` : String(s));
const dd = (d) => d.toLocaleDateString('en-GB', {timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit'});
const today = new Date().toLocaleDateString('en-GB', {timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric'});
// }}}

// {{{ Render
const heading = (text, note) => `
<tr>
  <td colspan="3" style="padding:24px 32px 0 32px;">
    <table role="presentation" width="100%" style="border-collapse:collapse;">
      <tr>
        <td style="font-family:${annot};font-size:10px;letter-spacing:0.24em;color:${rp.foam};text-transform:uppercase;white-space:nowrap;">${text}</td>
        <td style="font-family:${annot};font-size:9px;letter-spacing:0.12em;color:${rp.muted};text-align:right;white-space:nowrap;">${note}</td>
      </tr>
    </table>
    <div style="border-top:1px solid ${rp.pine};margin-top:7px;"></div>
    <div style="border-top:1px solid ${rp.overlay};margin-top:2px;"></div>
  </td>
</tr>`;

// Status is carried by the tag text as well as the colour: dark-mode
// reprocessing in Outlook and Apple Mail rewrites backgrounds and can flatten
// these hues into each other. Bracket tags also have guaranteed glyph
// coverage, which U+2713/U+2715 did not -- they rendered as tofu.
const mark = (status) => {
  if (FAILED.has(status)) return {glyph: '[X]', colour: rp.love, word: status.toUpperCase()};
  if (RUNNING.has(status)) return {glyph: '[~]', colour: rp.gold, word: status.toUpperCase()};
  return {glyph: '[+]', colour: rp.foam, word: 'PASS'};
};

const runRow = (run) => {
  const m = mark(run.status);
  return `
<tr>
  <td width="34" style="padding:8px 0 8px 32px;font-family:${annot};font-size:11px;color:${m.colour};vertical-align:top;white-space:nowrap;">${m.glyph}</td>
  <td style="padding:8px 10px;vertical-align:top;width:100%;">
    <div style="font-family:${draft};font-size:13px;color:${rp.text};">${short(run.title, 52)}</div>
    <div style="font-family:${annot};font-size:9px;letter-spacing:0.08em;color:${rp.muted};margin-top:4px;">
      ${run.workflow} &nbsp;|&nbsp; ${run.branch}@${run.sha} &nbsp;|&nbsp; ${run.event || 'n/a'}
    </div>
  </td>
  <td style="padding:8px 32px 8px 0;text-align:right;vertical-align:top;font-family:${annot};font-size:9px;letter-spacing:0.1em;color:${m.colour};white-space:nowrap;">
    <div>REV ${run.number ?? run.id}</div>
    <div style="color:${rp.muted};margin-top:4px;">${m.word}</div>
  </td>
</tr>`;
};

const plainRow = (left, right, tone) => `
<tr>
  <td colspan="2" style="padding:7px 10px 7px 32px;font-family:${draft};font-size:13px;color:${rp.text};">${left}</td>
  <td style="padding:7px 32px 7px 0;text-align:right;font-family:${annot};font-size:9px;letter-spacing:0.1em;color:${tone ?? rp.muted};white-space:nowrap;">${right}</td>
</tr>`;

const none = (text) => `
<tr><td colspan="3" style="padding:11px 32px;font-family:${draft};font-size:13px;font-style:italic;color:${rp.muted};">${text}</td></tr>`;

// The reporting window is bounded by run ids, not dates, so say so rather
// than implying a tidy week.
const windowNote = previousCursor === 0 ? 'first issue · latest 12 runs' : `runs ${previousCursor + 1}–${highest}`;

const html = `<!DOCTYPE html>
<html>
  <body style="margin:0;padding:30px 14px;background:${rp.base};">
    <table role="presentation" width="100%" style="max-width:600px;margin:0 auto;border-collapse:collapse;">
      <tr>
        <td style="background:${rp.surface};border:1px solid ${rp.pine};border-radius:8px;">
          <table role="presentation" width="100%" style="border-collapse:collapse;">

            <!-- sheet header -->
            <tr>
              <td colspan="3" style="padding:26px 32px 0 32px;">
                <table role="presentation" width="100%" style="border-collapse:collapse;">
                  <tr>
                    <td>
                      <div style="font-family:${annot};font-size:9px;letter-spacing:0.3em;color:${rp.muted};text-transform:uppercase;">forgejo actions &middot; ${REPO}</div>
                      <div style="font-family:${draft};font-size:27px;font-weight:bold;letter-spacing:0.02em;color:${rp.text};margin-top:11px;">Integration Sheet</div>
                    </td>
                    <td style="text-align:right;vertical-align:top;">
                      <div style="display:inline-block;border:2px solid ${stamp.colour};border-radius:3px;padding:7px 12px;">
                        <div style="font-family:${annot};font-size:12px;font-weight:bold;letter-spacing:0.16em;color:${stamp.colour};">${stamp.label}</div>
                      </div>
                    </td>
                  </tr>
                </table>
                <div style="font-family:${annot};font-size:10px;letter-spacing:0.08em;color:${rp.muted};margin-top:13px;">${stamp.note} &nbsp;&middot;&nbsp; ${windowNote}</div>
                <div style="border-top:2px solid ${rp.pine};margin-top:16px;"></div>
              </td>
            </tr>

            ${heading('workflows broken now', 'latest run of each workflow')}
            ${brokenNow.length ? brokenNow.map(runRow).join('\n') : none('Every workflow’s most recent run passed.')}

            ${heading('revision log', `${succeeded.length} pass · ${failures.length} fail · ${running.length} in progress`)}
            ${fresh.length ? fresh.slice(0, 14).map(runRow).join('\n') : none('No runs since the last issue of this sheet.')}
            ${fresh.length > 14 ? none(`… and ${fresh.length - 14} further runs not drawn.`) : ''}

            ${heading('open changes', `${openPulls.length} pull request${openPulls.length === 1 ? '' : 's'}`)}
            ${
              openPulls.length
                ? openPulls
                    .map((p) => plainRow(`#${p.number} &nbsp; ${short(p.title, 54)}`, `${p.author} · ${p.age}d`, p.age > 14 ? rp.gold : rp.muted))
                    .join('\n')
                : none('No open pull requests.')
            }

            ${heading('as-built', commitsTruncated ? `${commitCount} commits · page limit reached` : `${commitCount} commit${landed.length === 1 ? '' : 's'} in 7 days`)}
            ${
              landed.length
                ? landed.slice(0, 10).map((c) => plainRow(short(c.message, 58), `${c.sha} · ${dd(c.date)}`)).join('\n')
                : none('Nothing landed on main this week.')
            }
            ${landed.length > 10 ? none(commitsTruncated ? `… and at least ${landed.length - 10} further commits; Forgejo would not page past ${COMMIT_PAGE}.` : `… and ${landed.length - 10} further commits.`) : ''}

            <!-- title block -->
            <tr>
              <td colspan="3" style="padding:26px 32px 30px 32px;">
                <table role="presentation" width="100%" style="border-collapse:collapse;border:1px solid ${rp.pine};border-radius:4px;background:${rp.base};">
                  <tr>
                    ${[
                      ['drawn by', 'n8n @ inari'],
                      ['sheet', 'CI-01'],
                      ['date', today],
                      ['rev', String(highest)],
                    ]
                      .map(
                        ([k, v], i) => `<td style="padding:11px 12px;${i ? `border-left:1px solid ${rp.overlay};` : ''}">
                        <div style="font-family:${annot};font-size:8px;letter-spacing:0.2em;color:${rp.muted};text-transform:uppercase;">${k}</div>
                        <div style="font-family:${annot};font-size:11px;color:${rp.foam};margin-top:5px;white-space:nowrap;">${v}</div>
                      </td>`,
                      )
                      .join('')}
                  </tr>
                </table>
              </td>
            </tr>

          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;
// }}}

const subject = brokenNow.length
  ? `CI nonconforming · ${brokenNow.map((r) => r.workflow).join(', ')}`
  : failures.length
    ? `CI sheet · ${failures.length} failure${failures.length === 1 ? '' : 's'}, all since fixed`
    : `CI sheet · approved${fresh.length ? ` (${fresh.length} runs)` : ''}`;

return [{json: {subject, html}}];
